import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

import '../news_list/widgets/news_card.dart';
import '../currency_list/widgets/currency_card.dart';

class DashboardPage extends StatefulWidget {
  const DashboardPage({super.key});

  @override
  State<DashboardPage> createState() => _DashboardPageState();
}

class _DashboardPageState extends State<DashboardPage> {
  late Future<List<CurrencyModel>> _currenciesFuture;
  late Future<List<NewsModel>> _newsFuture;

  @override
  void initState() {
    super.initState();
    _initData();
  }

  void _initData() {
    final currencyRepository = context.read<CurrencyRepository>();
    final newsRepository = context.read<NewsRepository>();

    _currenciesFuture = currencyRepository
        .fetchRates(const CurrencyPageRequest())
        .then((CurrencyPage page) => page.items);

    _newsFuture = newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true));
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.dashboard)),
      body: FutureBuilder<List<dynamic>>(
        future: Future.wait([_currenciesFuture, _newsFuture]),
        builder: (BuildContext context, AsyncSnapshot<List<dynamic>> snapshot) {
          if (snapshot.connectionState == ConnectionState.waiting) {
            return const Center(child: CircularProgressIndicator());
          }

          if (!snapshot.hasData || snapshot.data == null) {
            return const Center(child: Text('No data'));
          }

          final List<CurrencyModel> currencies = snapshot.data![0] as List<CurrencyModel>;
          final List<NewsModel> news = snapshot.data![1] as List<NewsModel>;

          return ListView(
            padding: const EdgeInsets.fromLTRB(22, 24, 22, 40),
            children: [
              // Section title for currencies
              Text(
                context.loc.exchangeRates,
                style: context.fonts.semiBold12,
              ),
              const SizedBox(height: 8),
              ...currencies.map((CurrencyModel currency) {
                return Padding(
                  key: ValueKey(currency.id),
