{"content":"import 'package:mad_flutter_practicum/app/app.dart';

class HomePage extends StatefulWidget {
  const HomePage({super.key});

  @override
  State<HomePage> createState() => _HomePageState();
}

class _HomePageState extends State<HomePage> {
  int _selectedIndex = 0;

  static const List<_PageDescriptor> _pageDescriptors = <_PageDescriptor>[
    _PageDescriptor(
      page: CurrencyListPage(),
      iconBuilder: (bool isSelected) => TabWidget(
        assetPath: 'assets/icons/home.png',
        isSelected: isSelected,
      ),
      labelGetter: (AppLocalizations loc) => loc.currencyRate,
    ),
    _PageDescriptor(
      page: NewsListPage(),
      iconBuilder: (bool isSelected) => TabWidget(
        assetPath: 'assets/icons/news.png',
        isSelected: isSelected,
      ),
      labelGetter: (AppLocalizations loc) => loc.news,
    ),
    _PageDescriptor(
      page: ProfilePage(),
      iconBuilder: (bool isSelected) => const Icon(Icons.person),
      labelGetter: (AppLocalizations loc) => loc.profile,
    ),
    _PageDescriptor(
      page: DashboardPage(),
      iconBuilder: (bool isSelected) => TabWidget(
        assetPath: 'assets/icons/dashboard.png',
        isSelected: isSelected,
      ),
      labelGetter: (AppLocalizations loc) => loc.dashboard,
    ),
  ];

  void _onItemTapped(int index) {
    setState(() {
      _selectedIndex = index;
    });
  }

  @override
  Widget build(BuildContext context) {
    final Widget currentPage = _pageDescriptors[_selectedIndex].page;
    final AppLocalizations loc = context.loc;

    return Scaffold(
      body: currentPage,
      bottomNavigationBar: Container(
        decoration: BoxDecoration(
          boxShadow: <BoxShadow>[
            BoxShadow(
              color: context.colors.bottomNavBarShadow,
              blurRadius: 25,
              offset: Offset(0.0, 0.75),
            ),
          ],
        ),
        child: BottomNavigationBar(
          currentIndex: _selectedIndex,
          onTap: _onItemTapped,
          items: List.generate(
            _pageDescriptors.length,
            (int index) {
              final _PageDescriptor descriptor = _pageDescriptors[index];
              return BottomNavigationBarItem(
                icon: descriptor.iconBuilder(_selectedIsCurrent(index, currentPage)),
                label: descriptor.labelGetter(loc),
              );
            },
          ),
        ),
      ),
    );
  }

  bool _selectedIsCurrent(int index, Widget page) {
    return identical(page, _pageDescriptors[index].page);
  }
}

class _PageDescriptor {
  const _PageDescriptor({
    required this.page,
    required this.iconBuilder,
    required this.labelGetter,
  });

  final Widget page;
  final bool Function(bool isSelected) iconBuilder;
  final String Function(AppLocalizations) labelGetter;
}

class TabWidget extends StatelessWidget {
  const TabWidget({
    super.key,
    required this.assetPath,
    required this.isSelected,
  });

  final String assetPath;
  final bool isSelected;

  @override
  Widget build(BuildContext context) {
    if (assetPath.isEmpty) return const SizedBox.shrink();

    final ThemeColors colors = context.colors;

    return SizedBox.square(
      dimension: 24,
      child: Image.asset(
        assetPath,
        color: isSelected ? colors.bottomNavBarSelectedItem : colors.bottomNavBarUnselectedItem,
      ),
    );
  }
}
